// DOM Ready + TTI — 延迟到 load 事件后，确保 performance.timing 字段已填充
function captureFinalMetrics() {
  var t = performance.timing;
  var ns = t.navigationStart || t.fetchStart || 0;
  if (t.domContentLoadedEventEnd && ns) {
    setMetric('val-domready', t.domContentLoadedEventEnd - ns);
  }
  // TTI 近似 = domInteractive - navigationStart
  if (t.domInteractive && ns) {
    var el = document.getElementById('val-tti');
    if (el.textContent === '--') {
      setMetric('val-tti', t.domInteractive - ns);
    }
  }
}
if (document.readyState === 'complete') {
  captureFinalMetrics();
} else {
  window.addEventListener('load', captureFinalMetrics);
}

// ── 渲染完整时间线 ──

