var pt = performance.timing;
var navStart = pt.navigationStart || pt.fetchStart || 0;

// 现代 API (Navigation Timing Level 2)
var navEntries = performance.getEntriesByType('navigation');
var nav2 = navEntries.length > 0 ? navEntries[0] : null;

// ── 计算各阶段耗时 ──
var phases = [];

// Phase 1: 进程创建 → App.onLaunch (原生启动)
if (APP_T0 && APP_STARTUP) {
  var processStart = APP_T0 - APP_STARTUP; // 进程启动的估算时间戳
  phases.push({
    name: '进程创建 → JS 引擎就绪',
    phase: 'native',
    start: 0,
    dur: APP_STARTUP,
    detail: '原生进程 + 5+ Runtime 初始化'
  });
}

// Phase 2: App.onLaunch → 进入 webview 页面
if (APP_T0 && APP_PAGE_TS) {
  var dur = APP_PAGE_TS - APP_T0;
  if (dur > 0 && dur < 60000) {
    phases.push({
      name: 'App.onLaunch → 路由到首页',
      phase: 'native',
      start: phases.length > 0 ? phases[phases.length-1].start + phases[phases.length-1].dur : 0,
      dur: dur,
      detail: 'Vue 初始化 + Pinia + 路由匹配'
    });
  }
}

// Phase 3: 页面创建 → webview 开始加载 H5
if (APP_PAGE_TS && APP_WEBVIEW_TS) {
  var dur = APP_WEBVIEW_TS - APP_PAGE_TS;
  if (dur > 0 && dur < 60000) {
    phases.push({
      name: 'WebView 容器创建',
      phase: 'webview',
      start: phases.length > 0 ? phases[phases.length-1].start + phases[phases.length-1].dur : 0,
      dur: dur,
      detail: '创建 WebView 实例 + 设置 src'
    });
  }
}

// Phase 4: webview 开始加载 → H5 navigationStart
if (APP_WEBVIEW_TS && navStart) {
  var dur = navStart - APP_WEBVIEW_TS;
  if (dur > 0 && dur < 60000) {
    phases.push({
      name: 'WebView 发起请求 → 收到响应',
      phase: 'webview',
      start: phases.length > 0 ? phases[phases.length-1].start + phases[phases.length-1].dur : 0,
      dur: dur,
      detail: 'DNS + 连接 + 请求本地 hybrid 文件'

