// APP_T0 是 JS 引擎开始执行的时刻，原生启动时间 = APP_STARTUP
// 进程创建时刻 ≈ APP_T0 - APP_STARTUP
// 真实总耗时 = loadEventEnd - (APP_T0 - APP_STARTUP)
if (APP_T0 && pt.loadEventEnd && pt.loadEventEnd > 0) {
  totalMs = pt.loadEventEnd - APP_T0 + (typeof APP_STARTUP === 'number' ? APP_STARTUP : 0);
