13	  onLaunch: function () {
14	    console.log('[Perf] App.onLaunch at', APP_LAUNCH_TIME)
15	
16	    // #ifdef APP-PLUS
17	    try {
18	      // launchLoadedTime: 从 5+ Runtime 初始化到当前的时间 (ms)
19	      // 据此可以反推进程启动的时刻: processStart ≈ Date.now() - launchLoadedTime
20	      const startupDuration = plus.runtime.launchLoadedTime
21	      if (typeof startupDuration === 'number' && startupDuration > 0) {
22	        this.globalData.plusStartupDuration = startupDuration
23	        console.log('[Perf] plus.runtime.launchLoadedTime =', startupDuration, 'ms')
24	      }
